class Solution {
public:
    std::vector<int> closestNode(int n, std::vector<std::vector<int>>& edges, std::vector<std::vector<int>>& query) {
        std::vector<std::vector<int>> adj(n);
        for (const auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }
        std::vector<std::vector<int>> dist(n, std::vector<int>(n, -1));
        for (int i = 0; i < n; ++i) {
            dist[i][i] = 0;
            std::queue<int> q;
            q.push(i);
            while (!q.empty()) {
                int curr = q.front(); q.pop();
                for (int nxt : adj[curr]) {
                    if (dist[i][nxt] == -1) {
                        dist[i][nxt] = dist[i][curr] + 1;
                        q.push(nxt);
                    }
                }
            }
        }
        std::vector<int> ans;
        for (const auto& qm : query) {
            int u = qm[0], v = qm[1], target = qm[2];
            int best = u, minD = dist[target][u];
            for (int x = 0; x < n; ++x) {
                if (dist[u][x] + dist[x][v] == dist[u][v]) {
                    if (dist[target][x] < minD) {
                        minD = dist[target][x];
                        best = x;
                    }
                }
            }
            ans.push_back(best);
        }
        return ans;
    }
};

class Solution {
    public int[] closestNode(int n, int[][] edges, int[][] query) {
        java.util.List<Integer>[] adj = new java.util.ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new java.util.ArrayList<>();
        for (int[] e : edges) {
            adj[e[0]].add(e[1]);
            adj[e[1]].add(e[0]);
        }
        int[][] dist = new int[n][n];
        for (int[] row : dist) java.util.Arrays.fill(row, -1);
        for (int i = 0; i < n; i++) {
            dist[i][i] = 0;
            java.util.Queue<Integer> q = new java.util.LinkedList<>();
            q.offer(i);
            while (!q.isEmpty()) {
                int curr = q.poll();
                for (int nxt : adj[curr]) {
                    if (dist[i][nxt] == -1) {
                        dist[i][nxt] = dist[i][curr] + 1;
                        q.offer(nxt);
                    }
                }
            }
        }
        int[] ans = new int[query.length];
        for (int k = 0; k < query.length; k++) {
            int u = query[k][0], v = query[k][1], target = query[k][2];
            int best = u, minD = dist[target][u];
            for (int x = 0; x < n; x++) {
                if (dist[u][x] + dist[x][v] == dist[u][v]) {
                    if (dist[target][x] < minD) {
                        minD = dist[target][x];
                        best = x;
                    }
                }
            }
            ans[k] = best;
        }
        return ans;
    }
}

